const LEGAL_DE = {
impressum: { nav:"Impressum", h:"Impressum", sec:[
  ["Angaben gemäß § 5 DDG", `<p>${LG_FIRM}<br>Inhaber: ${LG_OWNER} (Einzelunternehmer)<br>Beusselstraße 18<br>10553 Berlin<br>Deutschland</p>`],
  ["Kontakt", `<p>Telefon: ${LG_TEL}<br>E-Mail: ${LG_MAIL}<br>WhatsApp: ${LG_TEL}</p>`],
  ["Umsatzsteuer", `<p>Umsatzsteuer-Identifikationsnummer gemäß § 27a Umsatzsteuergesetz: DE357158413</p>`],
  ["Angaben zur Meisterwerkstatt", `<p>Eingetragen in die Handwerksrolle der Handwerkskammer Berlin, Blücherstraße 68, 10961 Berlin.<br>Berufsbezeichnung: ${fillIn("z. B. Informationstechniker-Meister")}, verliehen in Deutschland.<br>Berufsrechtliche Regelung: Gesetz zur Ordnung des Handwerks (Handwerksordnung), einsehbar unter ${extL("https://www.gesetze-im-internet.de/hwo/", "gesetze-im-internet.de/hwo")}.</p><p>${fillIn("Nur angeben, wenn der Betrieb in die Handwerksrolle eingetragen ist. Sonst Abschnitt entfernen.")}</p>`],
  ["Verantwortlich für den Inhalt nach § 18 Abs. 2 MStV", `<p>${LG_OWNER}<br>Beusselstraße 18, 10553 Berlin</p>`],
  ["Verbraucherstreitbeilegung", `<p>Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.</p>`],
  ["Haftung für Inhalte und Links", `<p>Wir erstellen die Inhalte dieser Website mit Sorgfalt. Preise und Reparaturzeiten können sich ändern; verbindlich ist der Preis, den wir dir vor der Reparatur nennen. Für Inhalte externer Websites, auf die wir verlinken, sind deren Betreiber verantwortlich. Zum Zeitpunkt der Verlinkung waren keine Rechtsverstöße erkennbar. Werden uns Rechtsverletzungen bekannt, entfernen wir den Link umgehend.</p>`],
  ["Bildnachweise", `<p>Fotos der Werkstatt und des Ladens: ${LG_OWNER}, TipTop Service 24. Geräte- und Reparaturbilder: mit KI erstellt (ChatGPT). Logos der Gerätemarken: Eigentum der jeweiligen Hersteller.</p>`],
  ["Gestaltung und Umsetzung", `<p>Ronak</p>`]
]},

datenschutz: { nav:"Datenschutz", h:"Datenschutzerklärung", intro:"Hier steht, welche Daten wir verarbeiten, wenn du unsere Website nutzt, eine Reparatur anfragst oder uns ein Gerät verkaufst, wofür wir sie brauchen und welche Rechte du hast.", sec:[
  ["Verantwortlicher", `<p>Verantwortlich für die Datenverarbeitung auf dieser Website und in unserem Laden ist:</p><p>${LG_OWNER}<br>${LG_FIRM}<br>Beusselstraße 18, 10553 Berlin<br>Telefon: ${LG_TEL}<br>E-Mail: ${LG_MAIL}</p>`],
  ["Datenschutzbeauftragter", `<p>${fillIn("Wenn ein Datenschutzbeauftragter benannt ist: Name und Kontakt eintragen. Sonst diesen Abschnitt entfernen.")} Für alle Fragen zum Datenschutz erreichst du uns unter ${LG_MAIL}.</p>`],
  ["Das Wichtigste in Kürze", ulist([
    "Du kannst die Website nutzen, ohne dich anzumelden und ohne uns Daten zu nennen.",
    "Daten über dich erhalten wir erst, wenn du anrufst, schreibst, ein Formular abschickst oder eine WhatsApp-Nachricht sendest.",
    "Statistik- und Marketing-Dienste laden nur, wenn du ihnen in den Cookie-Einstellungen zustimmst.",
    "Website und Datenbank laufen auf unserem eigenen Server in Europa. Wir verkaufen keine Daten."
  ])],
  ["Rechtsgrundlagen", `<p>Wir verarbeiten personenbezogene Daten nach der Datenschutz-Grundverordnung (DSGVO) und dem Bundesdatenschutzgesetz (BDSG). Je nach Zweck stützen wir uns auf:</p>${ulist([
    "Art. 6 Abs. 1 lit. a DSGVO: deine Einwilligung, die du jederzeit mit Wirkung für die Zukunft widerrufen kannst,",
    "Art. 6 Abs. 1 lit. b DSGVO: die Erfüllung eines Vertrags oder vorvertraglicher Maßnahmen, etwa einer Reparaturanfrage,",
    "Art. 6 Abs. 1 lit. c DSGVO: gesetzliche Pflichten, etwa Aufbewahrungspflichten nach Handels- und Steuerrecht,",
    "Art. 6 Abs. 1 lit. f DSGVO: unser berechtigtes Interesse, etwa am sicheren Betrieb der Website."
  ])}<p>Für das Speichern und Auslesen von Informationen auf deinem Gerät gilt zusätzlich § 25 des Telekommunikation-Digitale-Dienste-Datenschutz-Gesetzes (TDDDG).</p>`],
  ["Hosting und Server-Logfiles", `<p>Die Website läuft auf einem virtuellen Server, den wir bei GoDaddy gemietet haben (${fillIn("Vertragspartner und Anschrift laut Auftragsverarbeitungsvertrag")}). Das Rechenzentrum steht in ${fillIn("Land")}. Mit GoDaddy besteht ein Vertrag zur Auftragsverarbeitung nach Art. 28 DSGVO. Eine Übermittlung an GoDaddy in den USA ist nicht ausgeschlossen; GoDaddy ist nach dem EU-US Data Privacy Framework zertifiziert, für das ein Angemessenheitsbeschluss der EU-Kommission besteht (Art. 45 DSGVO).</p><p>Bei jedem Aufruf speichert der Server technische Daten, die dein Browser übermittelt: IP-Adresse, Datum und Uhrzeit, aufgerufene Seite, zuvor besuchte Seite, Browser und Betriebssystem. Wir brauchen diese Daten, um die Website stabil und sicher zu betreiben und Angriffe abzuwehren (Art. 6 Abs. 1 lit. f DSGVO). Die Logfiles werden nach ${fillIn("14")} Tagen gelöscht, außer sie werden zur Aufklärung eines Sicherheitsvorfalls benötigt.</p>`],
  ["Verschlüsselung", `<p>Die Website ist per TLS verschlüsselt. Du erkennst das am Schloss-Symbol und an „https://“ in der Adresszeile. Daten, die du uns über die Website schickst, können so nicht von Dritten mitgelesen werden.</p>`],
  ["Cookies, lokaler Speicher und deine Einwilligung", `<p>Ohne Einwilligung speichern wir auf deinem Gerät nur, was für den Betrieb unbedingt nötig ist, zum Beispiel deine Sprachwahl und deine Cookie-Auswahl (§ 25 Abs. 2 Nr. 2 TDDDG). Statistik und Marketing setzen wir nur mit deiner Einwilligung ein (§ 25 Abs. 1 TDDDG, Art. 6 Abs. 1 lit. a DSGVO).</p><p>Deine Auswahl verwalten wir mit einer eigenen Lösung ohne externen Anbieter. Gespeichert werden die gewählten Kategorien, die Version des Hinweises, der Zeitpunkt und eine zufällige Kennung als Nachweis. Nach 12 Monaten fragen wir erneut. Du kannst deine Auswahl jederzeit über „Cookie-Einstellungen“ am Ende jeder Seite ändern oder widerrufen. Alle Einträge im Einzelnen stehen in der ${intL("cookies", "Cookie-Richtlinie")}.</p>`],
  ["Preisrechner, Rückruf und Reparaturanfrage", `<p>Den Preisrechner kannst du ohne Angaben zu deiner Person nutzen. Erst wenn du einen Rückruf anforderst oder das Formular „Reparaturanfrage“ absendest, verarbeiten wir die Daten, die du eingibst: Name, Telefon- oder WhatsApp-Nummer, Gerät und Modell, die gewählte Reparatur, deine Problembeschreibung sowie die gewünschte Art der Kontaktaufnahme und Reparatur.</p><p>Wir nutzen diese Daten nur, um deine Anfrage zu beantworten und die Reparatur durchzuführen (Art. 6 Abs. 1 lit. b DSGVO). Anfragen werden in unserem Verwaltungssystem auf unserem Server gespeichert und zusätzlich in eine Tabelle in Google Sheets übertragen, mit der unser Team arbeitet.</p><p>Anfragen, aus denen kein Auftrag wird, löschen wir nach 6 Monaten. Bei einem Auftrag bewahren wir Auftrags- und Rechnungsdaten so lange auf, wie es das Handels- und Steuerrecht verlangt, in der Regel 6 bis 10 Jahre (Art. 6 Abs. 1 lit. c DSGVO).</p>`],
  ["Google Sheets", `<p>Für die Bearbeitung der Anfragen nutzen wir Google Sheets (Google Workspace) der Google Ireland Limited, Gordon House, Barrow Street, Dublin 4, Irland. Mit Google besteht ein Vertrag zur Auftragsverarbeitung nach Art. 28 DSGVO. Eine Übermittlung an die Google LLC in den USA ist nicht ausgeschlossen. Die Google LLC ist nach dem EU-US Data Privacy Framework zertifiziert, für das ein Angemessenheitsbeschluss der EU-Kommission besteht (Art. 45 DSGVO). Zusätzlich gelten die EU-Standardvertragsklauseln.</p>`],
  ["WhatsApp", `<p>Mit den WhatsApp-Schaltflächen öffnest du einen Chat mit uns, in dem deine Reparatur oder dein Gerät schon als Nachricht vorausgefüllt ist. Beim Klick werden noch keine Daten an uns übertragen. Erst wenn du die Nachricht abschickst, erhalten wir deine Telefonnummer, deinen Profilnamen und den Inhalt der Nachricht.</p><p>WhatsApp wird von der WhatsApp Ireland Limited, Merrion Road, Dublin 4, D04 X2K5, Irland betrieben, die zum Meta-Konzern gehört. Es gelten die Datenschutzbestimmungen von WhatsApp; eine Verarbeitung in den USA ist möglich. Wir nutzen WhatsApp Business, um deine Anfrage zu beantworten (Art. 6 Abs. 1 lit. b DSGVO). Wenn du WhatsApp nicht nutzen möchtest, erreichst du uns genauso per Telefon, E-Mail, Formular oder im Laden. Chats löschen wir spätestens ${fillIn("6 Monate")} nach Abschluss der Reparatur.</p>`],
  ["Telefon und E-Mail", `<p>Wenn du uns anrufst oder schreibst, verarbeiten wir deine Angaben, um dein Anliegen zu bearbeiten (Art. 6 Abs. 1 lit. b oder f DSGVO). E-Mails löschen wir, sobald sie erledigt sind und keine Aufbewahrungspflicht besteht.</p>`],
  ["Spracheingabe", `<p>Über das Mikrofon-Symbol kannst du dein Problem diktieren. Die Spracheingabe startet erst, wenn du auf das Symbol tippst, unseren Hinweis bestätigst und deinem Browser den Zugriff auf das Mikrofon erlaubst. Die Umwandlung in Text übernimmt die Spracherkennung deines Browsers (Web Speech API). Je nach Browser wird die Aufnahme dafür an den Hersteller übertragen, bei Google Chrome an die Google LLC, bei Microsoft Edge an die Microsoft Corporation, bei Safari an Apple. Wir erhalten keine Audioaufnahme, nur den erkannten Text im Eingabefeld.</p><p>Rechtsgrundlage ist deine Einwilligung (Art. 6 Abs. 1 lit. a DSGVO), die du mit dem Bestätigen des Hinweises erteilst. Die Spracheingabe ist freiwillig; Tippen funktioniert genauso.</p>`],
  ["Automatische Erkennung deiner Problembeschreibung", `<p>Wenn du dein Problem in eigenen Worten beschreibst, erkennt die Website daraus Gerät, Modell und Reparatur und schlägt den passenden Preis vor. Die Auswertung läuft in deinem Browser bzw. auf unserem Server. Es werden keine Daten an externe KI-Anbieter übermittelt, und es gibt keine automatisierte Entscheidung im Sinne von Art. 22 DSGVO: Du entscheidest selbst, ob du den Vorschlag übernimmst.</p><p>${fillIn("Falls im Live-System ein externer KI-Dienst eingesetzt wird: Anbieter, Zweck und Übermittlung hier ergänzen.")}</p>`],
  ["Ankauf von Geräten", `<p>Wenn du uns ein Gerät verkaufst, verarbeiten wir die Angaben für den Ankaufvertrag: Name, Anschrift, Geburtsdatum, Art und Nummer deines Ausweises, Angaben zum Gerät einschließlich Seriennummer bzw. IMEI, Kaufpreis und Zahlungsdaten. Das ist für den Vertrag erforderlich (Art. 6 Abs. 1 lit. b DSGVO) und dient unserem berechtigten Interesse, den Ankauf gestohlener Geräte zu verhindern und nachweisen zu können, von wem wir ein Gerät erworben haben (Art. 6 Abs. 1 lit. f DSGVO). Dafür gleichen wir die IMEI mit Sperrlisten ab.</p><p>Die Ankaufsunterlagen bewahren wir ${fillIn("6 Jahre")} auf. Daten, die noch auf dem Gerät gespeichert sind, löschen wir vor dem Weiterverkauf vollständig.</p><p>Fragst du über die Website ein Angebot an, verarbeiten wir die Angaben zum Gerät, deinen Namen, deine Telefon- oder WhatsApp-Nummer und die Fotos, die du hochlädst oder mit der Kamera aufnimmst, um dir ein Angebot zu machen (Art. 6 Abs. 1 lit. b DSGVO). Bitte fotografiere nur das Gerät, keine Personen und keine Bildschirminhalte mit persönlichen Daten. Fotos zu Angeboten, aus denen kein Ankauf wird, löschen wir nach ${fillIn("30 Tagen")}.</p>`],
  ["Einsendung", `<p>Wenn du uns ein Gerät einschickst, verarbeiten wir deine Anschrift für den Rückversand. Name und Anschrift geben wir an den Versanddienstleister ${fillIn("z. B. DHL Paket GmbH")} weiter, soweit das für die Zustellung nötig ist (Art. 6 Abs. 1 lit. b DSGVO).</p>`],
  ["Deine Daten auf dem Gerät während der Reparatur", `<p>Wir greifen auf Inhalte deines Geräts nur zu, soweit es für Reparatur und Funktionstest unbedingt nötig ist. Wir kopieren keine Inhalte und sehen uns keine Fotos, Nachrichten oder Dateien an. Eine Datenrettung führen wir nur in deinem Auftrag durch; die geretteten Daten übergeben wir dir und löschen danach unsere Arbeitskopie.</p>`],
  ["Schriftarten", `<p>Die Schrift Archivo ist auf unserem eigenen Server gespeichert. Beim Seitenaufruf wird keine Verbindung zu Google Fonts oder anderen Schriftanbietern aufgebaut.</p>`],
  ["Links zu Google Maps und Instagram", `<p>Die Schaltflächen „Route“ und der Link zu Instagram sind einfache Links. Erst wenn du sie anklickst, wechselst du zu Google Maps (Google Ireland Limited) bzw. Instagram (Meta Platforms Ireland Limited, Merrion Road, Dublin 4, Irland); ab dann gelten deren Datenschutzbestimmungen. Vorher werden keine Daten an diese Anbieter übertragen.</p>`],
  ["Statistik mit Matomo (nur mit Einwilligung)", `<p>Wenn du der Kategorie „Statistik“ zustimmst, nutzen wir Matomo, eine Open-Source-Software zur Reichweitenmessung, die wir auf unserem eigenen Server in Deutschland betreiben. Matomo setzt dafür Cookies und erfasst unter anderem aufgerufene Seiten, Verweildauer, Gerätetyp und die Herkunft des Besuchs. Deine IP-Adresse wird vor der Speicherung um zwei Bytes gekürzt, sodass wir dich nicht identifizieren können. Die Daten verlassen unseren Server nicht und werden nach ${fillIn("13")} Monaten gelöscht.</p><p>Rechtsgrundlage ist deine Einwilligung (§ 25 Abs. 1 TDDDG, Art. 6 Abs. 1 lit. a DSGVO). Widerrufst du sie in den Cookie-Einstellungen, löschen wir die Matomo-Cookies auf deinem Gerät.</p>`],
  ["Marketing (nur mit Einwilligung)", `<p>Wenn du der Kategorie „Marketing“ zustimmst, binden wir das Conversion-Tracking von Google Ads (Google Ireland Limited) und das Meta-Pixel (Meta Platforms Ireland Limited) ein. Damit messen wir, ob eine Anzeige zu einer Anfrage geführt hat, und können Anzeigen gezielter in Berlin ausspielen. Dabei werden Cookies gesetzt und Nutzungsdaten wie IP-Adresse, Geräteinformationen und Interaktionen an Google bzw. Meta übermittelt, auch in die USA. Beide Unternehmen sind nach dem EU-US Data Privacy Framework zertifiziert. Für die Erhebung über das Meta-Pixel sind wir gemeinsam mit Meta verantwortlich (Art. 26 DSGVO).</p><p>Rechtsgrundlage ist deine Einwilligung (§ 25 Abs. 1 TDDDG, Art. 6 Abs. 1 lit. a DSGVO), die du jederzeit widerrufen kannst. ${fillIn("Nur aufnehmen, wenn Anzeigen geschaltet werden. Sonst Abschnitt und Kategorie entfernen.")}</p>`],
  ["Admin-Bereich", `<p>Der Verwaltungsbereich ist nur für unser Team zugänglich. Für die Anmeldung setzen wir technisch notwendige Cookies für die Sitzung und den Schutz vor Fremdzugriffen. Änderungen an Preisen und Anfragen werden protokolliert, damit nachvollziehbar ist, wer was geändert hat.</p>`],
  ["Speicherdauer", `<p>Wir speichern personenbezogene Daten nur so lange, wie es für den jeweiligen Zweck nötig ist oder das Gesetz es verlangt. Die Fristen für die einzelnen Verarbeitungen stehen in den Abschnitten oben. Danach löschen wir die Daten oder sperren sie, wenn eine Aufbewahrungspflicht besteht.</p>`],
  ["Deine Rechte", `<p>Du hast jederzeit das Recht auf</p>${ulist([
    "Auskunft über die Daten, die wir über dich speichern (Art. 15 DSGVO),",
    "Berichtigung unrichtiger Daten (Art. 16 DSGVO),",
    "Löschung (Art. 17 DSGVO),",
    "Einschränkung der Verarbeitung (Art. 18 DSGVO),",
    "Datenübertragbarkeit (Art. 20 DSGVO),",
    "Widerruf einer Einwilligung mit Wirkung für die Zukunft (Art. 7 Abs. 3 DSGVO)."
  ])}<p>Eine kurze Nachricht an ${LG_MAIL} oder ein Besuch im Laden genügt.</p>`],
  ["Widerspruchsrecht", `<p><strong>Verarbeiten wir Daten auf Grundlage unseres berechtigten Interesses (Art. 6 Abs. 1 lit. f DSGVO), kannst du aus Gründen, die sich aus deiner besonderen Situation ergeben, jederzeit widersprechen (Art. 21 Abs. 1 DSGVO). Wir verarbeiten die Daten dann nicht mehr, es sei denn, wir können zwingende schutzwürdige Gründe nachweisen, die deine Interessen überwiegen, oder die Verarbeitung dient der Geltendmachung, Ausübung oder Verteidigung von Rechtsansprüchen. Der Verarbeitung zu Werbezwecken kannst du jederzeit ohne Angabe von Gründen widersprechen (Art. 21 Abs. 2 DSGVO).</strong></p>`],
  ["Beschwerderecht", `<p>Du kannst dich bei einer Datenschutz-Aufsichtsbehörde beschweren (Art. 77 DSGVO). Für uns zuständig ist:</p><p>Berliner Beauftragte für Datenschutz und Informationsfreiheit<br>Alt-Moabit 59–61, 10555 Berlin<br>Telefon 030 13889-0<br>${extL("https://www.datenschutz-berlin.de")}</p>`],
  ["Pflicht zur Angabe und automatisierte Entscheidungen", `<p>Du bist weder gesetzlich noch vertraglich verpflichtet, uns Daten zu geben. Ohne Name und Telefonnummer können wir dich aber nicht zurückrufen, und ohne Ausweisdaten können wir kein Gerät ankaufen. Eine automatisierte Entscheidungsfindung einschließlich Profiling nach Art. 22 DSGVO findet nicht statt.</p>`],
  ["Änderungen", `<p>Wir passen diese Datenschutzerklärung an, wenn sich die Website, unsere Abläufe oder die Rechtslage ändern. Es gilt die hier veröffentlichte Fassung.</p>`]
]},

agb: { nav:"AGB", h:"Allgemeine Geschäftsbedingungen", intro:"Für Reparaturen und den Ankauf von Geräten bei TipTop Service 24.", sec:[
  ["@Teil A: Reparaturen"],
  ["§ 1 Geltungsbereich", abs([
    `Diese Allgemeinen Geschäftsbedingungen gelten für alle Reparatur-, Diagnose- und Ankaufverträge zwischen ${LG_OWNER}, handelnd unter „TipTop Service 24 Handy Reparatur Berlin“, Beusselstraße 18, 10553 Berlin (im Folgenden „TipTop“), und seinen Kundinnen und Kunden (im Folgenden „Kunde“), egal ob der Vertrag im Laden, telefonisch, per WhatsApp oder über die Website geschlossen wird.`,
    "Abweichende Bedingungen des Kunden gelten nur, wenn TipTop ihnen ausdrücklich in Textform zustimmt.",
    "Verbraucher ist jede natürliche Person, die ein Rechtsgeschäft zu Zwecken abschließt, die überwiegend weder ihrer gewerblichen noch ihrer selbständigen beruflichen Tätigkeit zugerechnet werden können (§ 13 BGB)."
  ])],
  ["§ 2 Preise auf der Website und Vertragsschluss", abs([
    "Die Preise im Preisrechner sind Endpreise inklusive 19 % Umsatzsteuer für die genannte Reparatur am angegebenen Modell. Die Darstellung auf der Website ist noch kein verbindliches Angebot. Mit „ab“ gekennzeichnete Preise sind Mindestpreise; der genaue Preis steht nach der Diagnose fest.",
    "Der Reparaturvertrag kommt zustande, wenn der Kunde das Gerät im Laden abgibt und den Reparaturauftrag bestätigt oder wenn TipTop einen telefonisch, per WhatsApp oder über die Website erteilten Auftrag für eine Einsendung bestätigt. Rückruf- und Anfrageformulare sind unverbindliche Anfragen.",
    "Stellt TipTop bei der Diagnose weitere Schäden fest, die den vereinbarten Preis erhöhen würden, holt TipTop vor jeder zusätzlichen Arbeit die Zustimmung des Kunden ein."
  ])],
  ["§ 3 Diagnose und Kostenvoranschlag", abs([
    `Die Fehlerdiagnose ist kostenlos, wenn der Kunde die Reparatur anschließend beauftragt. Lehnt der Kunde die Reparatur nach der Diagnose ab, berechnet TipTop ${fillIn("eine Pauschale von … €")}, sofern dies vor der Diagnose vereinbart wurde.`,
    "Ein Kostenvoranschlag ist unverbindlich, wenn er nicht ausdrücklich als verbindlich bezeichnet ist. Zeichnet sich eine wesentliche Überschreitung ab, informiert TipTop den Kunden, bevor weitergearbeitet wird (§ 649 BGB)."
  ])],
  ["§ 4 Ersatzteile: Original und Premium", abs([
    "„Original“ bezeichnet Ersatzteile des Geräteherstellers oder Teile, die der Hersteller für die Reparatur bereitstellt.",
    "„Premium“ bezeichnet hochwertige, kompatible Ersatzteile anderer Hersteller, die TipTop vor dem Einbau auf Funktion, Helligkeit, Farbdarstellung und Touch prüft. Bei Displays können Helligkeit, Farbdarstellung und Stromverbrauch leicht vom Originalteil abweichen. Einige Hersteller zeigen nach dem Einbau eines Fremdteils einen Hinweis in den Einstellungen an, zum Beispiel „Unbekanntes Teil“ bei iPhones; die Funktion ist dadurch nicht eingeschränkt.",
    "Der Kunde wählt die Teilequalität vor der Reparatur. Ausgebaute Altteile erhält er auf Wunsch zurück; sonst entsorgt TipTop sie fachgerecht."
  ])],
  ["§ 5 Pflichten des Kunden vor der Reparatur", abs([
    "Der Kunde sichert vor der Abgabe alle Daten auf dem Gerät. Auch bei sorgfältiger Arbeit kann es bei Reparaturen zum Verlust gespeicherter Daten kommen. Für Datenverlust haftet TipTop nur nach § 12.",
    "Der Kunde entfernt SIM- und Speicherkarten, Hüllen und Zubehör.",
    "Ist es für den Funktionstest nötig, teilt der Kunde den Entsperrcode mit oder ist bei der Rückgabe zum Test anwesend. Die Angabe ist freiwillig; ohne Code kann TipTop nur eingeschränkt testen."
  ])],
  ["§ 6 Reparaturdauer", `<p>Angegebene Reparaturzeiten, etwa „unter einer Stunde“, sind Richtwerte. Muss ein Teil bestellt werden, nennt TipTop die voraussichtliche Dauer. Verbindlich sind nur ausdrücklich zugesagte Termine.</p>`],
  ["§ 7 Einsendung", abs([
    "Bei Einsendung verpackt der Kunde das Gerät transportsicher und ohne Zubehör. Der Rückversand ist für den Kunden kostenlos. Bei Verbrauchern trägt TipTop beim Rückversand die Gefahr bis zur Übergabe.",
    `Wird ein Vertrag ausschließlich über Fernkommunikationsmittel geschlossen, steht Verbrauchern ein Widerrufsrecht zu. Einzelheiten stehen in der ${intL("widerruf", "Widerrufsbelehrung")}.`
  ])],
  ["§ 8 Zahlung, Abholung und nicht abgeholte Geräte", abs([
    `Der Reparaturpreis ist bei Rückgabe des Geräts fällig. Zahlung ist bar oder mit Karte ${fillIn("oder per Überweisung")} möglich.`,
    "Für seine Forderungen aus dem Reparaturvertrag steht TipTop ein gesetzliches Pfandrecht an dem Gerät zu (§ 647 BGB).",
    `Holt der Kunde das reparierte Gerät nicht innerhalb von 4 Wochen nach der Fertigmeldung ab, erinnert ihn TipTop und setzt eine angemessene Frist. Nach erfolglosem Fristablauf kann TipTop ein angemessenes Lagergeld verlangen oder nach den gesetzlichen Vorschriften vorgehen. ${fillIn("Frist und Lagergeld prüfen.")}`
  ])],
  ["§ 9 Gewährleistung", `<p>Für Reparaturleistungen und eingebaute Teile gelten die gesetzlichen Mängelrechte. Die Verjährungsfrist beträgt zwei Jahre ab Abnahme (§ 634a BGB). Mängel meldet der Kunde im Laden, telefonisch oder per E-Mail.</p>`],
  ["§ 10 Garantie", abs([
    "Zusätzlich zu den gesetzlichen Mängelrechten gibt TipTop eine freiwillige Garantie auf eingebaute Ersatzteile und die ausgeführte Arbeit. Sie beträgt je nach Reparatur und Teilequalität bis zu 12 Monate; die genaue Dauer steht auf der Rechnung.",
    `Garantiegeber ist ${LG_OWNER}, TipTop Service 24 Handy Reparatur Berlin, Beusselstraße 18, 10553 Berlin. Die Garantie gilt in Deutschland. Im Garantiefall prüft TipTop das Gerät und repariert es kostenlos oder tauscht das betroffene Teil aus. Dazu bringt der Kunde das Gerät mit der Rechnung in den Laden oder schickt es ein.`,
    "Ausgeschlossen sind Schäden durch Sturz, Druck, Bruch (insbesondere Glasbruch), Flüssigkeit, unsachgemäße Behandlung und Eingriffe Dritter nach der Reparatur.",
    "Die gesetzlichen Rechte des Kunden, insbesondere die Mängelrechte nach § 9, bleiben von der Garantie unberührt und werden durch sie nicht eingeschränkt. Die Inanspruchnahme der gesetzlichen Mängelrechte ist unentgeltlich."
  ])],
  ["§ 11 Wasserschäden, Platinenreparatur und Datenrettung", `<p>Bei Wasserschäden, Platinenreparaturen (Mikrolöten, IC-Tausch) und Datenrettung kann TipTop keinen Erfolg garantieren, weil sich der Zustand oft erst während der Arbeit zeigt. Gelingt die Reparatur nicht, berechnet TipTop nur den vorher vereinbarten Diagnose- bzw. Aufwandspreis. Durch Korrosion vorgeschädigte Geräte können auch nach erfolgreicher Reparatur später weitere Fehler zeigen; dafür gilt die Garantie nach § 10 nicht. Die gesetzlichen Mängelrechte bleiben unberührt.</p>`],
  ["§ 12 Haftung", abs([
    "TipTop haftet unbeschränkt bei Vorsatz und grober Fahrlässigkeit, für Schäden aus der Verletzung des Lebens, des Körpers oder der Gesundheit sowie nach dem Produkthaftungsgesetz.",
    "Bei einfacher Fahrlässigkeit haftet TipTop nur bei Verletzung einer wesentlichen Vertragspflicht, also einer Pflicht, deren Erfüllung die ordnungsgemäße Durchführung des Vertrags erst ermöglicht und auf deren Einhaltung der Kunde regelmäßig vertrauen darf. Die Haftung ist dann auf den vorhersehbaren, vertragstypischen Schaden begrenzt.",
    "Für den Verlust von Daten haftet TipTop bei einfacher Fahrlässigkeit nur in Höhe des Aufwands, der bei ordnungsgemäßer Datensicherung durch den Kunden für die Wiederherstellung nötig gewesen wäre."
  ])],
  ["@Teil B: Ankauf von Geräten"],
  ["§ 13 Angebot und Vertragsschluss", abs([
    "Das Angebot, das der Kunde per WhatsApp oder über die Website erhält, ist eine unverbindliche Einschätzung auf Grundlage seiner Angaben und gilt 7 Tage.",
    "Den verbindlichen Kaufpreis legt TipTop nach Prüfung des Geräts im Laden fest. Der Ankaufvertrag kommt mit Unterzeichnung im Laden zustande, auf Papier oder digital am Tablet."
  ])],
  ["§ 14 Voraussetzungen für den Ankauf", abs([
    "Der Verkäufer muss mindestens 18 Jahre alt sein und sich mit einem gültigen amtlichen Lichtbildausweis ausweisen.",
    "Der Verkäufer versichert, dass er Eigentümer des Geräts ist und frei darüber verfügen darf, dass das Gerät nicht gestohlen, unterschlagen, finanziert, geleast oder mit Rechten Dritter belastet ist und dass seine Angaben zum Zustand stimmen.",
    "Aktivierungssperren wie „Wo ist?“ bei Apple oder die Google-Kontosperre müssen vor dem Verkauf aufgehoben sein. TipTop prüft IMEI bzw. Seriennummer gegen Sperrlisten."
  ])],
  ["§ 15 Daten auf dem Gerät", `<p>Der Verkäufer sichert und löscht seine Daten vor dem Verkauf und setzt das Gerät auf Werkseinstellungen zurück. TipTop löscht verbleibende Daten vor dem Weiterverkauf mit einem zertifizierten Löschverfahren und ist nicht verpflichtet, Daten zu sichern oder herauszugeben.</p>`],
  ["§ 16 Kaufpreis und Zahlung", `<p>Der Kaufpreis wird bei Vertragsschluss sofort bar ausgezahlt oder per Überweisung auf ein Konto des Verkäufers gezahlt.</p>`],
  ["§ 17 Falsche Angaben und gesperrte Geräte", `<p>Stellt sich heraus, dass die Versicherungen nach § 14 nicht zutreffen, insbesondere dass das Gerät gestohlen oder gesperrt ist, kann TipTop vom Vertrag zurücktreten und den Kaufpreis zurückverlangen. Gesetzliche Ansprüche bleiben unberührt. Bei Verdacht auf eine Straftat darf TipTop das Gerät der Polizei übergeben.</p>`],
  ["@Teil C: Schlussbestimmungen"],
  ["§ 18 Verbraucherstreitbeilegung", `<p>TipTop ist nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.</p>`],
  ["§ 19 Anwendbares Recht und Gerichtsstand", abs([
    "Es gilt deutsches Recht unter Ausschluss des UN-Kaufrechts. Bei Verbrauchern gilt diese Rechtswahl nur, soweit ihnen dadurch nicht der Schutz zwingender Vorschriften des Staates entzogen wird, in dem sie ihren gewöhnlichen Aufenthalt haben.",
    "Ist der Kunde Kaufmann, juristische Person des öffentlichen Rechts oder öffentlich-rechtliches Sondervermögen, ist Gerichtsstand Berlin."
  ])],
  ["§ 20 Unwirksame Bestimmungen", `<p>Sind einzelne Bestimmungen unwirksam, bleibt der Vertrag im Übrigen wirksam. An die Stelle der unwirksamen Bestimmung treten die gesetzlichen Vorschriften (§ 306 BGB).</p>`]
]},

widerruf: { nav:"Widerruf", h:"Widerrufsbelehrung", intro:"Gilt für Reparaturaufträge, die du ausschließlich aus der Ferne erteilst, zum Beispiel für eine Einsendung per Website, Telefon oder WhatsApp.", sec:[
  ["Widerrufsrecht", `<p>Sie haben das Recht, binnen vierzehn Tagen ohne Angabe von Gründen diesen Vertrag zu widerrufen.</p><p>Die Widerrufsfrist beträgt vierzehn Tage ab dem Tag des Vertragsabschlusses.</p><p>Um Ihr Widerrufsrecht auszuüben, müssen Sie uns (${LG_OWNER}, TipTop Service 24 Handy Reparatur Berlin, Beusselstraße 18, 10553 Berlin, Telefon 030 81475791, E-Mail tiptophandyreparatur@gmail.com) mittels einer eindeutigen Erklärung (z. B. ein mit der Post versandter Brief oder E-Mail) über Ihren Entschluss, diesen Vertrag zu widerrufen, informieren. Sie können dafür das beigefügte Muster-Widerrufsformular verwenden, das jedoch nicht vorgeschrieben ist. Sie können den Widerruf auch über die Widerrufsfunktion „Vertrag widerrufen“ auf dieser Seite erklären.</p><p>Zur Wahrung der Widerrufsfrist reicht es aus, dass Sie die Mitteilung über die Ausübung des Widerrufsrechts vor Ablauf der Widerrufsfrist absenden.</p>`],
  ["Folgen des Widerrufs", `<p>Wenn Sie diesen Vertrag widerrufen, haben wir Ihnen alle Zahlungen, die wir von Ihnen erhalten haben, einschließlich der Lieferkosten (mit Ausnahme der zusätzlichen Kosten, die sich daraus ergeben, dass Sie eine andere Art der Lieferung als die von uns angebotene, günstigste Standardlieferung gewählt haben), unverzüglich und spätestens binnen vierzehn Tagen ab dem Tag zurückzuzahlen, an dem die Mitteilung über Ihren Widerruf dieses Vertrags bei uns eingegangen ist. Für diese Rückzahlung verwenden wir dasselbe Zahlungsmittel, das Sie bei der ursprünglichen Transaktion eingesetzt haben, es sei denn, mit Ihnen wurde ausdrücklich etwas anderes vereinbart; in keinem Fall werden Ihnen wegen dieser Rückzahlung Entgelte berechnet.</p><p>Haben Sie verlangt, dass die Dienstleistungen während der Widerrufsfrist beginnen sollen, so haben Sie uns einen angemessenen Betrag zu zahlen, der dem Anteil der bis zu dem Zeitpunkt, zu dem Sie uns von der Ausübung des Widerrufsrechts hinsichtlich dieses Vertrags unterrichten, bereits erbrachten Dienstleistungen im Vergleich zum Gesamtumfang der im Vertrag vorgesehenen Dienstleistungen entspricht.</p>`],
  ["Wann das Widerrufsrecht gilt", ulist([
    "Das Widerrufsrecht gilt für Verbraucher bei Verträgen, die ausschließlich über Fernkommunikationsmittel geschlossen werden, etwa wenn du eine Einsendung über die Website, per Telefon, E-Mail oder WhatsApp beauftragst.",
    "Für Aufträge, die du in unserem Laden erteilst, besteht kein gesetzliches Widerrufsrecht.",
    "Das Widerrufsrecht erlischt, wenn wir die Reparatur vollständig erbracht haben und du vorher ausdrücklich zugestimmt hast, dass wir vor Ablauf der Widerrufsfrist beginnen, und bestätigt hast, dass du dein Widerrufsrecht mit vollständiger Erfüllung verlierst (§ 356 Abs. 4 BGB)."
  ])],
  ["Muster-Widerrufsformular", `<div class="lg-form"><p>(Wenn Sie den Vertrag widerrufen wollen, dann füllen Sie bitte dieses Formular aus und senden Sie es zurück.)</p><p>An ${LG_OWNER}, TipTop Service 24 Handy Reparatur Berlin, Beusselstraße 18, 10553 Berlin, E-Mail: tiptophandyreparatur@gmail.com:</p><p>Hiermit widerrufe(n) ich/wir (*) den von mir/uns (*) abgeschlossenen Vertrag über den Kauf der folgenden Waren (*)/die Erbringung der folgenden Dienstleistung (*)</p><p>Bestellt am (*)/erhalten am (*)</p><p>Name des/der Verbraucher(s)</p><p>Anschrift des/der Verbraucher(s)</p><p>Unterschrift des/der Verbraucher(s) (nur bei Mitteilung auf Papier)</p><p>Datum</p><p>(*) Unzutreffendes streichen.</p></div>`]
]},

cookies: { nav:"Cookies", h:"Cookie-Richtlinie", intro:"Welche Cookies und Speichereinträge diese Website nutzt, wofür und wie lange.", sec:[
  ["Cookies und lokaler Speicher", `<p>Cookies und Einträge im lokalen Speicher (localStorage) sind kleine Datensätze, die dein Browser für eine Website ablegt. Wir nutzen sie sparsam: Ohne deine Einwilligung setzen wir nur, was für den Betrieb der Website unbedingt nötig ist. Werbe- und Analyse-Cookies von Dritten laden nie, bevor du zugestimmt hast.</p>`],
  ["Notwendig", `<p>Diese Einträge brauchen wir, damit die Website funktioniert und sich an deine Auswahl erinnert. Rechtsgrundlage ist § 25 Abs. 2 Nr. 2 TDDDG; eine Einwilligung ist nicht erforderlich.</p>${ckTable("de", "necessary")}`],
  ["Statistik", `<p>Nur mit deiner Einwilligung. Hilft uns zu verstehen, welche Seiten und Reparaturen gefragt sind, damit wir die Website verbessern können.</p>${ckTable("de", "stats")}`],
  ["Marketing", `<p>Nur mit deiner Einwilligung. Misst, ob unsere Anzeigen zu Anfragen führen. ${fillIn("Kategorie entfernen, wenn keine Anzeigen geschaltet werden.")}</p>${ckTable("de", "marketing")}`],
  ["Rechtsgrundlage und Widerruf", `<p>Optionale Cookies setzen wir auf Grundlage deiner Einwilligung (§ 25 Abs. 1 TDDDG, Art. 6 Abs. 1 lit. a DSGVO). Du kannst sie jederzeit über „Cookie-Einstellungen“ am Ende jeder Seite widerrufen. Ablehnen ist genauso einfach wie Zustimmen und hat keine Nachteile: Preisrechner, Formulare und WhatsApp funktionieren immer. Widerrufst du eine Einwilligung, löschen wir die zugehörigen Cookies auf deinem Gerät. Mehr dazu in der ${intL("datenschutz", "Datenschutzerklärung")}.</p>`],
  ["Cookies im Browser löschen", `<p>Du kannst Cookies und Website-Daten auch selbst in deinem Browser löschen oder blockieren, meist unter „Einstellungen“, „Datenschutz“ oder „Website-Daten“. Danach fragen wir beim nächsten Besuch erneut nach deiner Auswahl.</p>`]
]},

barrierefreiheit: { nav:"Barrierefreiheit", h:"Barrierefreiheit", intro:"Wir möchten, dass alle Menschen ihr Gerät bei uns reparieren lassen können, auch online.", sec:[
  ["Unsere Dienstleistung", `<p>Auf dieser Website kannst du Reparaturpreise berechnen, eine Reparatur anfragen, einen Rückruf anfordern und uns ein Gerät mit Fotos zum Ankauf anbieten. Alle Funktionen sind auch telefonisch und in unserem Laden verfügbar.</p>`],
  ["Standard", `<p>Wir orientieren uns an den Web Content Accessibility Guidelines (WCAG) 2.1 auf Stufe AA und der harmonisierten Norm EN 301 549.</p>`],
  ["So setzen wir Barrierefreiheit um", ulist([
    "Alle Funktionen sind mit der Tastatur bedienbar; der Fokus ist immer deutlich sichtbar.",
    "Texte und Bedienelemente haben ausreichenden Farbkontrast, und Informationen hängen nie nur an einer Farbe.",
    "Schaltflächen, Formularfelder und Bilder haben Beschriftungen und Alternativtexte für Screenreader; Fehlermeldungen werden angesagt.",
    "Die Seite lässt sich auf 200 % vergrößern und funktioniert auf allen Bildschirmgrößen ohne seitliches Scrollen.",
    "Ist in deinem System „Bewegung reduzieren“ eingestellt, schalten wir Animationen ab.",
    "Die Seite ist auf Deutsch und Englisch verfügbar, und die Sprache ist für Screenreader ausgezeichnet.",
    "Den Preis kannst du tippen, antippen oder diktieren."
  ])],
  ["Bekannte Einschränkungen", ulist([
    "Der Vorher-nachher-Vergleich ist ein Regler. Mit der Tastatur bedienst du ihn mit den Pfeiltasten; die Bilder sind zusätzlich beschrieben.",
    "WhatsApp, Google Maps und Instagram sind externe Dienste, auf deren Barrierefreiheit wir keinen Einfluss haben. Telefon, E-Mail und Formular stehen als Alternativen bereit.",
    `${fillIn("Ergebnis der abschließenden Prüfung vor dem Livegang ergänzen.")}`
  ])],
  ["Barriere melden", `<p>Wenn dir eine Barriere auffällt oder du Hilfe brauchst, melde dich per E-Mail an ${LG_MAIL} oder telefonisch unter ${LG_TEL}. Wir antworten innerhalb von ${fillIn("14")} Tagen und helfen dir in der Zwischenzeit auf einem anderen Weg.</p>`],
  ["Zuständige Marktüberwachungsbehörde", `<p>Marktüberwachungsstelle der Länder für die Barrierefreiheit von Produkten und Dienstleistungen (MLBF AöR)<br>Carl-Miller-Straße 6, 39112 Magdeburg<br>${extL("https://www.mlbf-barrierefrei.de")}</p>`],
  ["Stand dieser Erklärung", `<p>Selbstbewertung vom 14. November 2026. ${fillIn("Prüfen, ob TipTop als Kleinstunternehmen (weniger als 10 Beschäftigte und höchstens 2 Mio. € Jahresumsatz) vom Barrierefreiheitsstärkungsgesetz ausgenommen ist. Die Erklärung kann dann freiwillig bleiben.")}</p>`]
]}
};
